    if dr is not None:
        # The object is the non-background colored region on one side.
        vals = {}
        for r in range(h):
            if r == dr:
                continue
            for c in range(w):
                v = g[r][c]
                if v not in (2, 3):
                    vals[v] = vals.get(v, 0) + 1
        if vals:
            color = max(vals, key=vals.get)
            cells = [(r, c) for r in range(h) for c in range(w)
                     if g[r][c] == color]
            top, bottom = min(r for r, c in cells), max(r for r, c in cells)
            if bottom < dr:
                # Slide the object toward the divider if there is a gap.
                shift = dr - 1 - bottom
                if shift:
                    for r, c in cells:
                        g[r][c] = 3
                    for r, c in cells:
                        g[r + shift][c] = color
                marker = top + shift - 1
                if marker >= 0 and marker != dr:
                    g[marker] = [8] * w
            else:
                shift = dr + 1 - top
                if shift:
                    for r, c in cells:
                        g[r][c] = 3
                    for r, c in cells:
